const buildInitialNotificationConfigMap = () =>
  Object.fromEntries(
    Object.entries(notificationConfigProfiles).map(([id, profile]) => [id, profile.entries]),
  ) as Record<string, NotificationConfigEntry[]>;

const buildWorkflowNotificationSwitchRules = (entry: NotificationConfigEntry): WorkflowNotificationSwitchRule[] => {
  const isCip = entry.scene.includes('CIP') || entry.name.includes('CIP');
  const isIntake = entry.scene.includes('入账') || entry.name.includes('补类');
  const baseFlow = entry.scene || '待选择流程';
  const forceMode = entry.content.includes('强制') ? '强制开启' : '按偏好发送';
  const canMuteMode = entry.content.includes('可关闭') ? '可关闭' : '按偏好发送';
  const primaryChannel = entry.channel || '站内 + 钉钉 H5';

  if (isCip) {
    return [
      {
        id: `${entry.id}-submit`,
        flow: baseFlow,
        node: '流程发起',
        event: '提交成功',
        channel: '站内 + 钉钉 H5',
        mode: '强制开启',
        reviewer: entry.owner,
        audit: '提交人、流程版本、表单快照和通知渠道留痕',
        enabled: entry.enabled,
        tone: 'blue',
      },
      {
        id: `${entry.id}-finance`,
        flow: baseFlow,
        node: '财务复核',
        event: '节点到达 / SLA 超时',
        channel: primaryChannel,
        mode: forceMode,
        reviewer: '资产会计',
        audit: '金额、节点、处理人和 SLA 触发原因留痕',
        enabled: entry.enabled,
        tone: 'green',
      },
      {
        id: `${entry.id}-erp`,
        flow: baseFlow,
        node: 'ERP 回写',
        event: '推送失败 / 回执异常',
        channel: '邮件 + 站内',
        mode: '强制开启',
        reviewer: '集成管理员',
        audit: '接口、批次、错误摘要和人工重放人留痕',
        enabled: true,
        tone: 'orange',
      },
    ];
  }

  if (isIntake) {
    return [
      {
        id: `${entry.id}-class`,
        flow: baseFlow,
        node: '资产补类',
        event: '资产分类缺失',
        channel: primaryChannel,
        mode: '强制开启',
        reviewer: '资产管理员',
        audit: '待建资产批次、缺失分类和补类人留痕',
        enabled: entry.enabled,
        tone: 'blue',
      },
      {
        id: `${entry.id}-number`,
        flow: baseFlow,
        node: '编号预览',
        event: '编号冲突',
        channel: '站内 + 钉钉 H5',
        mode: '强制开启',
        reviewer: entry.owner,
        audit: '冲突编号、序列规则和处理动作留痕',
        enabled: entry.enabled,
        tone: 'orange',
      },
    ];
  }

  return [
    {
      id: `${entry.id}-done`,
      flow: baseFlow,
      node: '流程归档',
      event: entry.trigger || '流程归档',
      channel: primaryChannel,
      mode: canMuteMode,
      reviewer: entry.owner,
      audit: entry.content || '通知开关变更写入审计',
      enabled: entry.enabled,
      tone: entry.tone,
    },
    {
      id: `${entry.id}-fail`,
      flow: baseFlow,
      node: '外部推送',
      event: '推送失败',
      channel: '邮件 + 站内',
      mode: '强制开启',
      reviewer: '平台运维',
      audit: '失败摘要、回执和补偿处理人留痕',
      enabled: true,
      tone: 'red',
    },
  ];
};

const buildInitialWorkflowNotificationSwitchMap = () =>
  Object.fromEntries(
    notificationConfigProfiles['system-workflow-notification-switch'].entries.map((entry) => [
      entry.id,
      buildWorkflowNotificationSwitchRules(entry),
    ]),
  ) as Record<string, WorkflowNotificationSwitchRule[]>;

