const getFlowDefinitionDetail = (row: FlowPlatformProductRow): FlowDefinitionDetail => {
  const knownDetail = flowDefinitionKnownDetails[row.id] ?? {};
  return {
    businessObject: knownDetail.businessObject ?? row.category,
    publishScope: knownDetail.publishScope ?? `${row.category} / ${row.enabled} / ${row.publishedAt}`,
    owner: knownDetail.owner ?? row.baseline.publisher,
    formBinding: knownDetail.formBinding ?? `${row.form[0]}（${row.form[1]}）`,
    todoFields: knownDetail.todoFields ?? ['流程名称', '当前节点', '处理角色', 'SLA 状态'],
    triggerConditions: knownDetail.triggerConditions ?? [`${row.category}业务对象创建或状态变更`, `${row.enabled}时允许发起`, `${row.state}版本通过发布检查`],
    versionTrack: knownDetail.versionTrack ?? [row.baseline.current, row.baseline.no, row.baseline.time],
    auditRecords: knownDetail.auditRecords ?? [`${row.baseline.time} ${row.baseline.publisher}维护版本基线`, `${row.publishedAt}发布状态：${row.state}`],
    releaseNotes: knownDetail.releaseNotes ?? [`发布范围：${row.category}`, `启停状态：${row.enabled}`, `发布检查：${row.checks.length} 项`],
    nodes: knownDetail.nodes ?? row.nodes,
    form: knownDetail.form ?? row.form,
    sla: knownDetail.sla ?? row.sla,
    checks: knownDetail.checks ?? row.checks,
  };
};

