const buildNumberingPreviewRows = (
  entry: MasterDataConfigEntry,
  detail: NumberingRuleDetail,
  mode: 'preview' | 'conflict' = 'preview',
): NumberingPreviewRow[] => {
  const categoryCode = entry.code.includes('CIP')
    ? 'CIP-EQP'
    : entry.code.includes('IT')
      ? 'IT-LAPTOP'
      : 'SMT';
  const sequenceHint = detail.sequenceScope.includes('小类') ? '小类序列' : '公共序列';
  const conflictTone: SystemHubTone = mode === 'conflict' ? 'orange' : 'green';
  return [
    {
      source: entry.code.includes('CIP') ? 'CIP-2026-01 转固批次' : 'PO-202606-018 待建资产',
      category: entry.objectType,
      quantity: entry.code.includes('CIP') ? '2 行' : '3 行',
      generated: `${categoryCode}-2606-0001 ~ ${categoryCode}-2606-0003`,
      result: mode === 'conflict' ? `${sequenceHint}可用，0 个历史锁号冲突` : `${sequenceHint}试算通过`,
      tone: conflictTone,
    },
    {
      source: entry.code.includes('IT') ? '员工领用批次 IT-0621' : '手工新增批次 MAN-0620',
      category: detail.previewSample,
      quantity: entry.code.includes('IT') ? '5 行' : '1 行',
      generated: `${categoryCode}-2606-0004${entry.code.includes('IT') ? ` ~ ${categoryCode}-2606-0008` : ''}`,
      result: mode === 'conflict' ? '责任人/位置/小类校验通过' : '数量拆行后逐行占号',
      tone: 'cyan',
    },
    {
      source: entry.code.includes('CIP') ? 'CIP 费用化处理行' : '历史编号快照',
      category: entry.scope,
      quantity: entry.code.includes('CIP') ? '0 行' : '已锁号',
      generated: entry.code.includes('CIP') ? '费用化行不生成资产号' : `${categoryCode}-2605-0098`,
      result: mode === 'conflict' ? '保留历史编号，不允许无痕改号' : detail.rollbackPlan,
      tone: entry.tone,
    },
  ];
};

