function Panel({
  title,
  action,
  children,
  className = '',
}: {
  title?: string;
  action?: string;
  children: ReactNode;
  className?: string;
}) {
  return (
    <section className={`workspace-panel ${className}`}>
      {title ? (
        <div className="workspace-panel-head">
          <h2>{title}</h2>
          {action ? <button type="button">{action}</button> : null}
        </div>
      ) : null}
      {children}
    </section>
  );
}

function WorkspaceModuleMock({
  mock,
  onPreviewAction,
}: {
  mock: ModuleMock;
  onPreviewAction: (preview: RouteActionPreview) => void;
}) {
  const Icon = mock.icon;

  return (
    <section className="workspace-module-mock" aria-label={`${mock.title}模块看板`}>
      <div className="workspace-module-mock-visual">
        <img src={mock.visual} alt="" loading="eager" decoding="async" />
        <span>{mock.eyebrow}</span>
      </div>
      <div className="workspace-module-mock-copy">
        <div className="workspace-module-mock-title">
          <IsoIcon icon={Icon} src={mock.visual} alt="" />
          <div>
            <span>{mock.eyebrow}</span>
            <strong>{mock.title}</strong>
          </div>
        </div>
        <p>{mock.summary}</p>
        <div className="workspace-module-mock-stats" aria-label={`${mock.title}关键指标`}>
          {mock.stats.map((stat) => (
            <div key={stat.label}>
              <span>{stat.label}</span>
              <strong>{stat.value}</strong>
              <small>{stat.note}</small>
            </div>
          ))}
        </div>
        <button
          type="button"
          className="workspace-module-mock-action"
          onClick={() =>
            onPreviewAction({
              title: mock.title,
              source: `${mock.eyebrow}模块入口`,
              routeTarget: mock.routeTarget,
              description: mock.summary,
              primaryLabel: mock.action,
              icon: mock.icon,
              visual: mock.visual,
              stats: mock.stats,
            })
          }
        >
          {mock.action}
          <ArrowRight />
        </button>
      </div>
      <div className="workspace-module-mock-rows" aria-label={`${mock.title}业务清单`}>
        {mock.rows.map((row) => (
          <div key={row.label} className={`is-${row.tone}`}>
            <span>{row.label}</span>
            <strong>{row.value}</strong>
            <small>{row.note}</small>
          </div>
        ))}
      </div>
      <div className="workspace-module-mock-flow" aria-label={`${mock.title}流程`}>
        {mock.steps.map((step, index) => (
          <span key={step.label}>
            <em>{String(index + 1).padStart(2, '0')}</em>
            <strong>{step.label}</strong>
            <small>{step.note}</small>
          </span>
        ))}
      </div>
    </section>
  );
}

function WorkbenchSystemModuleBoard({
  item,
  board,
  onOpenAction,
}: {
  item: WorkspaceMenuItem;
  board: SystemModuleBoardConfig;
  onOpenAction: (action: SystemModuleBoardConfig['actions'][number]) => void;
}) {
  return (
    <section className="workspace-system-module-board" aria-label={`${item.label}专用功能面板`}>
      <header>
        <div>
          <span>{board.badge}</span>
          <strong>{board.title}</strong>
          <p>{board.subtitle}</p>
        </div>
        <div className="workspace-system-module-actions" aria-label={`${item.label}专用操作`}>
          {board.actions.map((action) => {
            const ActionIcon = action.icon;
            return (
              <button key={action.label} type="button" onClick={() => onOpenAction(action)}>
                <ActionIcon />
                {action.label}
              </button>
            );
          })}
        </div>
      </header>

      <div className="workspace-system-module-metrics" aria-label={`${item.label}专用指标`}>
        {board.metrics.map((metric) => (
          <article key={metric.label} className={`is-${metric.tone}`}>
            <span>{metric.label}</span>
            <strong>{metric.value}</strong>
            <small>{metric.note}</small>
          </article>
        ))}
      </div>

      <div className="workspace-system-module-lanes" aria-label={`${item.label}能力编排`}>
        {board.lanes.map((lane) => (
          <article key={lane.title} className={`is-${lane.tone}`}>
            <h3>{lane.title}</h3>
            <p>{lane.description}</p>
            <div>
              {lane.items.map((entry) => (
                <span key={entry}>{entry}</span>
              ))}
            </div>
          </article>
        ))}
      </div>

      <div className="workspace-system-module-preview" aria-label={`${item.label}专用配置预览`}>
        <div className="workspace-system-module-preview-head">
          {board.tableHeaders.map((header) => (
            <span key={header}>{header}</span>
          ))}
        </div>
        {board.rows.map((row) => (
          <div key={row.cells.join('-')} className={`workspace-system-module-preview-row is-${row.tone}`}>
            {row.cells.map((cell) => (
              <span key={cell}>{cell}</span>
            ))}
          </div>
        ))}
      </div>

      <footer className="workspace-system-module-evidence" aria-label={`${item.label}专用验收依据`}>
        {board.evidence.map((entry) => (
          <span key={entry}>
            <CheckCircle2 />
            {entry}
          </span>
        ))}
      </footer>
    </section>
  );
}

