    setSelectedEntryId(defaultEntryId ?? nextEntries[0]?.id ?? profile.entries[0].id);
    setMenuStructureFilter('全部结构');
    setUserGrantTaskSearchQuery('');
    setUserOrgSearchQuery('');
    setRoleMemberSearchQuery('');
    setDepartmentLeadTaskSearchQuery('');
    setDataSubjectSearchQuery('');
