const ASSET_TRANSFER_WORKFLOW = 'ASSET_TRANSFER';
const ASSET_TRANSFER_ENTRY_FALLBACK = '/disposals/transfer/new';

function buildMyAssetsTransferEntry(entryUrl?: string) {
  const rawEntry = entryUrl?.trim() || ASSET_TRANSFER_ENTRY_FALLBACK;
  const [pathAndQuery, hash = ''] = rawEntry.split('#');
  const queryStart = pathAndQuery.indexOf('?');
  const pathname = queryStart >= 0 ? pathAndQuery.slice(0, queryStart) : pathAndQuery;
  const query = queryStart >= 0 ? pathAndQuery.slice(queryStart + 1) : '';
  const params = new URLSearchParams(query);
  params.set('source', 'workbench');
  params.set('menu', 'my-assets');
  const search = params.toString();
  return `${pathname || ASSET_TRANSFER_ENTRY_FALLBACK}${search ? `?${search}` : ''}${hash ? `#${hash}` : ''}`;
}

function getAssetTransferBlockReason(
  availability: WorkflowStartAvailability | null,
  isLoading: boolean,
  isError: boolean,
  errorReason = '',
) {
  if (isLoading) return '正在校验流程状态';
  if (isError) return errorReason || '无审批发起权限或暂无法校验流程状态';
  if (availability?.canStart) return '';
  const status = String(availability?.status ?? '').toUpperCase();
  if (status === 'DISABLED') return availability?.blockReason || '流程已停用';
  if (status === 'DRAFT') return availability?.blockReason || '流程未发布';
  if (status === 'UNCONFIGURED') return availability?.blockReason || '流程未配置';
  return availability?.blockReason || '流程不可发起';
}

function getAssetTransferAvailabilityErrorReason(error: unknown) {
  const message = error instanceof Error ? error.message.trim() : '';
  if (/403|forbidden|无权限|无权|权限|未授权/i.test(message)) {
    return message || '无审批发起权限，无法发起资产调拨流程';
  }
  if (message) {
    return `暂无法校验流程状态：${message}`;
  }
  return '无审批发起权限或暂无法校验流程状态';
}

